import '@servicenow/sdk/global'
import { Flow, trigger, wfa, action } from '@servicenow/sdk/automation'

// =============================================================================
// Test Flow: WaitForADuration inside conditional blocks
// Tests wait for duration with if/else branches using outputs as datapills
// =============================================================================
export const flowWaitForDurationConditional = Flow(
    {
        $id: Now.ID['flow-wait-duration-conditional'],
        name: 'Wait For Duration Conditional',
        description: 'WaitForADuration with if/else logic test',
        flowPriority: 'MEDIUM',
        runAs: 'system',
        runWithRoles: [],
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['wait-duration-conditional-trigger'] },
        {
            table: 'incident',
            condition: 'active=true',
            run_on_extended: 'false',
            run_flow_in: 'foreground',
            run_when_user_list: [],
            run_when_setting: 'both',
            run_when_user_setting: 'any',
        }
    ),
    (params) => {
        // Initial wait before conditional
        const initialWait = wfa.flowLogic.waitForADuration({
            $id: Now.ID['wait-duration-conditional-initial'],
            durationType: 'explicit_duration',
            duration: Duration({
                days: 0,
                hours: 0,
                minutes: 0,
                seconds: 3,
            }),
        })

        // Log initial wait result
        wfa.action(
            action.core.log,
            {
                $id: Now.ID['wait-duration-conditional-log-initial'],
            },
            {
                log_level: 'info',
                log_message: `Initial wait: ${wfa.dataPill(initialWait.total_duration, 'string')}`,
            }
        )

        // Conditional based on trigger priority
        wfa.flowLogic.if(
            {
                $id: Now.ID['wait-duration-conditional-if'],
                condition: `${wfa.dataPill(params.trigger.current.priority, 'string')}==1`,
                annotation: 'High priority branch',
            },
            () => {
                // High priority - short wait
                const urgentWait = wfa.flowLogic.waitForADuration({
                    $id: Now.ID['wait-duration-conditional-urgent'],
                    durationType: 'explicit_duration',
                    duration: Duration({
                        days: 0,
                        hours: 0,
                        minutes: 0,
                        seconds: 2,
                    }),
                })

                wfa.action(
                    action.core.log,
                    {
                        $id: Now.ID['wait-duration-conditional-log-urgent'],
                    },
                    {
                        log_level: 'warn',
                        log_message: `URGENT: ${wfa.dataPill(urgentWait.total_duration, 'string')}`,
                    }
                )
            }
        )

        wfa.flowLogic.else(
            {
                $id: Now.ID['wait-duration-conditional-else'],
                annotation: 'Normal priority branch',
            },
            () => {
                // Normal priority - longer wait
                const normalWait = wfa.flowLogic.waitForADuration({
                    $id: Now.ID['wait-duration-conditional-normal'],
                    durationType: 'explicit_duration',
                    duration: Duration({
                        days: 0,
                        hours: 0,
                        minutes: 0,
                        seconds: 10,
                    }),
                })

                wfa.action(
                    action.core.log,
                    {
                        $id: Now.ID['wait-duration-conditional-log-normal'],
                    },
                    {
                        log_level: 'info',
                        log_message: `Normal: ${wfa.dataPill(normalWait.total_duration, 'string')}`,
                    }
                )
            }
        )

        // Final log referencing initial wait output outside conditionals
        wfa.action(
            action.core.log,
            {
                $id: Now.ID['wait-duration-conditional-log-final'],
            },
            {
                log_level: 'info',
                log_message: `Flow completed. Initial was: ${wfa.dataPill(initialWait.total_duration, 'string')}`,
            }
        )
    }
)
